import { View, Text, Pressable, StyleSheet } from "react-native";
import { useState } from "react";
import { registerRootComponent } from "expo";

const TABS = ["Нүүр", "Сагс", "Профайл"];

function App() {
  const [tab, setTab] = useState("Нүүр");
  const [cart, setCart] = useState(0);

  function Body() {
    if (tab === "Сагс") return <Text nativeID="body" style={styles.h}>Сагсанд {cart} бараа</Text>;
    if (tab === "Профайл") return <Text nativeID="body" style={styles.h}>Профайл</Text>;
    return (
      <View style={styles.pad}>
        <Text nativeID="body" style={styles.h}>Нүүр</Text>
        <Pressable nativeID="add" style={styles.btn} onPress={() => setCart((c) => c + 1)}>
          <Text style={styles.btnText}>Сагслах</Text>
        </Pressable>
      </View>
    );
  }

  return (
    <View style={styles.container}>
      <View style={styles.bodyWrap}><Body /></View>
      <View style={styles.tabbar}>
        {TABS.map((t, i) => (
          <Pressable key={t} nativeID={"tab" + i} testID="tab" style={styles.tab}>
            {/* энд бичнэ үү: onPress-оор таб солиж, идэвхтэйг тодотго */}
            <Text style={styles.tabText}>{t}</Text>
            {t === "Сагс" && cart > 0 && <Text nativeID="badge" style={styles.badge}>{cart}</Text>}
          </Pressable>
        ))}
      </View>
    </View>
  );
}

const styles = StyleSheet.create({
  container: { flex: 1 },
  bodyWrap: { flex: 1 },
  pad: { flex: 1, padding: 24, gap: 14, justifyContent: "center", alignItems: "center" },
  h: { fontSize: 22, fontWeight: "bold", textAlign: "center" },
  btn: { backgroundColor: "#2563eb", padding: 14, borderRadius: 12, alignItems: "center" },
  btnText: { color: "#fff", fontWeight: "bold" },
  tabbar: { flexDirection: "row", borderTopWidth: 1, borderTopColor: "#e5e7eb" },
  tab: { flexGrow: 1, paddingVertical: 12, alignItems: "center" },
  active: { backgroundColor: "#dbeafe" },
  tabText: { fontWeight: "600", color: "#334155" },
  badge: { position: "absolute", top: 2, right: 20, backgroundColor: "#dc2626", color: "#fff", fontSize: 12, fontWeight: "bold", minWidth: 18, textAlign: "center", paddingHorizontal: 5, borderRadius: 999 },
});

registerRootComponent(App);

